from abc import ABCMeta, abstractmethod
import six


@six.add_metaclass(ABCMeta)
class Device(object):

    _vendor = None
    _model = None
    _version = None

    @abstractmethod
    def __init__(self, **kwargs):
        pass

    @classmethod
    def get_vendor(cls):
        return cls._vendor

    @classmethod
    def get_model(cls):
        return cls._model

    @classmethod
    def get_version(cls):
        return cls._version


@six.add_metaclass(ABCMeta)
class MCS(Device):
    def __init__(self, starter=None, **kwargs):
        super(MCS, self).__init__(**kwargs)
        self._starter = starter
        self._config = kwargs

    def startup(self):
        self._starter.start()

    def stop(self):
        self._starter.stop()

    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def disconnect(self):
        pass

    @abstractmethod
    def set_frequency(self, frequency, timeout=None):
        """

        :param frequency:
        :param timeout: set frequency operation timeout.
        :return:
        """
        pass

    @abstractmethod
    def set_phases_according_to_angles(self,
                                       vertical_angle,
                                       horizontal_angle,
                                       vertical_distance,
                                       horizontal_distance,
                                       output_group_id,
                                       input_group_id):
        """

        :param angle:
        :return:
        """
        pass

    @abstractmethod
    def set_phase(self, phase, input_channel, output_channel, ):
        """

        :param phase:
        :param input_channel:
        :param output_channel:
        :return:
        """
        pass

    @abstractmethod
    def get_phase(self, input_channel, output_channel, **kwargs):
        """

        :param input_channel:
        :param output_channel:
        :return:
        """

    def set_phases(self, phase, begin_input_channel=1, end_input_channel=64, output_channel=1):
        """

        :param begin_phase:
        :param begin_channel:
        :param end_channel:
        :param step:
        :return:
        """
        pass

    @abstractmethod
    def set_attenuation(self, attenuation, input_channel, output_channel):
        """

        :param attenuation:
        :param input_channel:
        :param output_channel:
        :return:
        """
        pass

    @abstractmethod
    def get_attenuation(self, input_channel, output_channel, **kwargs):
        """

        :param input_channel:
        :param output_channel:
        :return:
        """

    @abstractmethod
    def set_odd_attenuations(self, attenuation, output_channel=1, begin_input_channel=1, end_input_channel=64):
        """

        :param attenuation:
        :param output_channel:
        :param begin_input_channel:
        :param end_input_channel:
        :return:
        """
        pass

    @abstractmethod
    def set_even_attenuations(self, attenuation, output_channel=1, begin_input_channel=1, end_input_channel=64):
        """

        :param attenuation:
        :param output_channel:
        :param begin_input_channel:
        :param end_input_channel:
        :return:
        """
        pass

    def set_matrix_number(self, number):
        """
        Set matrix number for Topyoung device

        :param number: matrix number, 64 or 1024
        :return: True or False indicating success or failure
        """
        raise NotImplementedError

    def read_matrix_number(self):
        """
        Read matrix number for Topyoung device

        :return: matrix number
        """
        raise NotImplementedError

    def set_position(self, matrix_positions):
        """
        set position for Topyoung device
        :param dict matrix_positions:
            e.g {1: [("A1", 1, 1), ("A2", 2, 2), ("A3", 1, 3)],
                 2: [("A4", 1, 1), ("A5", 2, 2), ("A6", 1, 3)]
            dict key is matrix id, 1 or 2
            dict value is positions, like List[Tuple[int, int, int]] positions: list of positions to set
                e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
                where each tuple is (A port, row number, column number)
        :return: True or False indicating success or failure
        """
        raise NotImplementedError

    def read_position(self, matrix_id):
        """
        Read position for Topyoung device

        :param matrix_id: matrix id, 1 or 2
        :return: list of positions
            e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
            where each tuple is (A port, row number, column number)
        """
        raise NotImplementedError

    def set_aedis(self, matrix_id, horizontal_d_value, vertical_d_value,
                 ul_horizontal_d_value, ul_vertical_d_value):
        """
        Set aedis for Topyoung device

        :param matrix_id: matrix id, 1 or 2
        :param horizontal_d_value: horizontal distance value
        :param vertical_d_value: vertical distance value
        :param ul_horizontal_d_value: uplink horizontal distance value
        :param ul_vertical_d_value: uplink vertical distance value
        :return: True or False indicating success or failure
        """
        raise NotImplementedError

    def read_aedis(self):
        """
        Read aedis for Topyoung device

        :return: aedis value
        """
        raise NotImplementedError

    def set_beam(self, port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                even_attenuation_enable, event_attenuation_value,
                odd_attenuation_enable, odd_attenuation_value):
        """
        Set beam parameters only available for Topyoung device

        :param port: B port number, e.g "B1", "B2"
        :param matrix_id: matrix id, 1 or 2
        :param horizontal_beam_angle: horizontal beam angle
        :param vertical_beam_angle: vertical beam angle
        :param even_attenuation_enable: enable even channel attenuation, 0 disabled, 1 enabled
        :param event_attenuation_value: even channel attenuation value
        :param odd_attenuation_enable: enable odd channel attenuation, 0 disabled, 1 enabled
        :param odd_attenuation_value: odd channel attenuation value
        :return: True or False indicating success or failure
        """
        raise NotImplementedError
